import React, { useState } from 'react';
import './CSS/LoginSignup.css';

const LoginSignup = () => {
  // 1. State for toggling between Login and Signup
  const [state, setState] = useState("Login"); 

  // 2. State for capturing form input
  const [formData, setFormData] = useState({
    username: "",
    password: "",
    email: ""
  });

  // 3. Update formData as the user types
  const changeHandler = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  // 4. Login Function
  const login = async () => {
    console.log("Login Function Executed", formData);
    let responseData;
    try {
      const response = await fetch('http://localhost:4000/login', {
        method: 'POST',
        headers: {
          'Accept': 'application/json',
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(formData),
      });
      responseData = await response.json();

      if (responseData.success) {
        localStorage.setItem('auth-token', responseData.token);
        window.location.replace("/");
      } else {
        alert(responseData.errors);
      }
    } catch (err) {
      alert("Error: Could not connect to the server. Is your backend running on port 4000?");
    }
  };

  // 5. Signup Function
  const signup = async () => {
    console.log("Signup Function Executed", formData);
    let responseData;
    try {
      const response = await fetch('http://localhost:4000/signup', {
        method: 'POST',
        headers: {
          'Accept': 'application/json',
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(formData),
      });
      responseData = await response.json();

      if (responseData.success) {
        localStorage.setItem('auth-token', responseData.token);
        window.location.replace("/");
      } else {
        alert(responseData.errors);
      }
    } catch (err) {
      alert("Error: Could not connect to the server. Is your backend running on port 4000?");
    }
  };

  return (
    <div className='loginsignup'>
      <div className="loginsignup-container">
        <h1>{state}</h1>
        <div className="loginsignup-fields">
          {/* Conditional Rendering: Show Name only for Signup */}
          {state === "Signup" ? (
            <input 
              name='username' 
              value={formData.username} 
              onChange={changeHandler} 
              type="text" 
              placeholder='Your Name' 
            />
          ) : null}
          
          <input 
            name='email' 
            value={formData.email} 
            onChange={changeHandler} 
            type="email" 
            placeholder='Email Address' 
          />
          <input 
            name='password' 
            value={formData.password} 
            onChange={changeHandler} 
            type="password" 
            placeholder='Password' 
          />
        </div>
        
        <button onClick={() => { state === "Login" ? login() : signup() }}>Continue</button>
        
        {state === "Signup" ? (
          <p className="loginsignup-login">
            Already have an account? <span onClick={() => setState("Login")}>Login Here</span>
          </p>
        ) : (
          <p className="loginsignup-login">
            Create an account? <span onClick={() => setState("Signup")}>Click Here</span>
          </p>
        )}
        
        <div className="loginsignup-agree">
          <input type="checkbox" name='agree' id='agree' required />
          <p>By continuing, I agree to the terms of use & privacy policy.</p>
        </div>
      </div>
    </div>
  );
};

export default LoginSignup;
